import { createClient, BNB, signerFromPrivateKey } from "@altananetwork/sdk";

const client = createClient({ chains: [BNB] });
const admin  = signerFromPrivateKey("0x...");
const wallet = await client.createWallet({ signer: admin });

const session = await client.grantSession({
  wallet,
  signer: admin,
  permissions: {
    calls: [{ to: "0xUniswapRouter..." }],
    spend: [{
      limit: 50n * 10n ** 18n,
      period: "day",
      token: "0xUSDT...",
    }],
  },
  expiry: Math.floor(Date.now() / 1000) + 7 * 24 * 60 * 60,
});

// Documented constraint surface is EXACTLY these three axes:
//   calls[].to   -> contract allowlist (no 4-byte selector field documented)
//   spend[]      -> { limit, period, token }  (asset scope == token address)
//   expiry       -> unix seconds
// NOT documented anywhere I fetched: selector allowlist, approval threshold,
// per-call value cap, calldata-argument constraints.

client.execute(opts: ClientExecuteOptions): Promise<ExecuteResult>;

const result = await client.execute({
  wallet,
  signer,
  calls: { to: "0xRecipient...", value: 1_000_000_000_000_000n }
});
// docs: admin execute "auto-registers the admin key in Keystore";
// session execute is "byte-exact" (strict parameter matching).
// Who broadcasts (self-bundled vs Altana bundler) is NOT stated on this page.

client.revokeSession(opts: ClientRevokeSessionOptions): Promise<ExecuteResult>;

await client.revokeSession({ wallet, signer: admin, session });
// One userOp, two atomic ops: revoke in the KeyStore contract (direct, not the
// Controller) + strip the session's authority from the smart account.
// Access control: "Only the wallet itself (executing inside its own userOp) or a
// designated validator can revoke a key." Other callers revert at the modifier.
// "On the chain where the key is registered the effect is immediate, and no
//  off-chain coordination is required."

// package: @altananetwork/sdk   (NO version string published anywhere I fetched)
hireErc8183Agent(wallet, signer, params, opts)
hireErc8183Agent(session, params, opts)      // <- session-key path is 3-arg
getErc8183Job(network, jobId)
getErc8183DeliverableUrl(network, jobId)
settleErc8183Job(wallet, signer, params, opts)
buildClaimRefundCall(chainId, jobId)

// ERC8183_ADDRESSES: documented as exporting kernel (AgenticCommerce),
// EvaluatorRouter, OptimisticPolicy, ERC-8004 registry and $U token for
// chain 56 and 97 -- but the page prints NO hex values, and
// /concepts/networks lists only the two KeyStore addresses.
// => the ERC-8183 kernel address on BSC mainnet is an OPEN GAP.

// Doc quote on the session path:
// "The session-key path works too (hireErc8183Agent(session, params, opts)),
//  so a scoped key with an on-chain spend limit caps what an autonomous agent
//  can ever escrow."
